class LmdbEmptyCacheClearTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:empty-cache:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:empty-cache:predicate");
	private static final Value OBJECT = VF.createLiteral("a dictionary-backed committed value");

	@Test
	void addOnlyCommitsAvoidCachePublicationAndAreImmediatelyVisible(@TempDir Path directory) throws Exception {
		CountingCacheStore store = new CountingCacheStore(directory.toFile());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection writer = repository.getConnection();
				RepositoryConnection observer = repository.getConnection()) {
			long cacheBefore = committedTransactionId(store.cache);
			int commitCallsBefore = store.operations.commitCalls.get();
			writer.begin();
			writer.add(SUBJECT, PREDICATE, OBJECT);
			writer.commit();
			assertTrue(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false),
					"another connection must see the complete committed statement immediately");
			assertEquals(cacheBefore, committedTransactionId(store.cache),
					"ordinary RDF publication must not dirty the empty unused-ID cache environment");
			assertEquals(commitCallsBefore, store.operations.commitCalls.get());

			writer.begin();
			writer.add(SUBJECT, PREDICATE, OBJECT);
			writer.commit();
			writer.begin();
			writer.add(SUBJECT, PREDICATE, VF.createLiteral(true));
			writer.setNamespace("empty", "urn:empty-cache:");
			writer.commit();
			assertTrue(observer.hasStatement(SUBJECT, PREDICATE, VF.createLiteral(true), false));
			assertEquals("urn:empty-cache:", observer.getNamespace("empty"));
			writer.begin();
			writer.setNamespace("namespaceOnly", "urn:namespace-only:");
			writer.commit();
			assertEquals("urn:namespace-only:", observer.getNamespace("namespaceOnly"));
			assertEquals(cacheBefore, committedTransactionId(store.cache));
			assertEquals(commitCallsBefore, store.operations.commitCalls.get());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void rollbackKeepsRdfAndNamespaceUnpublishedAndAllowsReuse(@TempDir Path directory) throws Exception {
		CountingCacheStore store = new CountingCacheStore(directory.toFile());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection writer = repository.getConnection();
				RepositoryConnection observer = repository.getConnection()) {
			long cacheBefore = committedTransactionId(store.cache);
			writer.begin();
			writer.add(SUBJECT, PREDICATE, OBJECT);
			writer.setNamespace("rolledBack", "urn:rolled-back:");
			writer.rollback();
			assertFalse(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			assertNull(observer.getNamespace("rolledBack"));
			assertEquals(cacheBefore, committedTransactionId(store.cache));

			Value replacement = VF.createLiteral("committed after rollback");
			writer.begin();
			writer.add(SUBJECT, PREDICATE, replacement);
			writer.commit();
			assertTrue(observer.hasStatement(SUBJECT, PREDICATE, replacement, false));
			assertFalse(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			assertEquals(cacheBefore, committedTransactionId(store.cache));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void removalStillClearsRealRetirementsAndPreservesSnapshotValues(@TempDir Path directory) throws Exception {
		CountingCacheStore store = new CountingCacheStore(directory.toFile());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection writer = repository.getConnection();
				RepositoryConnection reader = repository.getConnection();
				RepositoryConnection observer = repository.getConnection()) {
			writer.begin();
			writer.add(SUBJECT, PREDICATE, OBJECT);
			writer.commit();
			reader.begin(IsolationLevels.SNAPSHOT);
			assertTrue(reader.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			long cacheBefore = committedTransactionId(store.cache);
			int commitCallsBefore = store.operations.commitCalls.get();
			writer.begin();
			writer.remove(SUBJECT, PREDICATE, OBJECT);
			writer.commit();
			assertFalse(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			assertTrue(committedTransactionId(store.cache) > cacheBefore,
					"real unused-ID retirement work must still be committed and cleared");
			assertTrue(store.operations.commitCalls.get() > commitCallsBefore);
			try (RepositoryResult<Statement> statements = reader.getStatements(SUBJECT,
					PREDICATE, null, false)) {
				assertTrue(statements.hasNext());
				assertEquals(OBJECT, statements.next().getObject(),
						"the pinned dictionary must still resolve the value");
				assertFalse(statements.hasNext());
			}
			reader.rollback();
			writer.begin();
			writer.add(SUBJECT, PREDICATE, VF.createLiteral("after retirement"));
			writer.commit();
			assertTrue(observer.hasStatement(SUBJECT, PREDICATE, VF.createLiteral("after retirement"), false));
			assertFalse(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void consumedCacheCommitFailurePreservesPublicationAndWholeRetry(@TempDir Path directory) throws Exception {
		CountingCacheStore store = new CountingCacheStore(directory.toFile());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection writer = repository.getConnection();
				RepositoryConnection observer = repository.getConnection()) {
			writer.begin();
			writer.add(SUBJECT, PREDICATE, OBJECT);
			writer.setNamespace("generation", "urn:original:");
			writer.commit();
			Value replacement = VF.createLiteral("replacement must publish only after complete retry");
			store.operations.failNextCommit.set(true);
			writer.begin();
			writer.remove(SUBJECT, PREDICATE, OBJECT);
			writer.add(SUBJECT, PREDICATE, replacement);
			writer.setNamespace("generation", "urn:replacement:");
			RuntimeException failure = assertThrows(RuntimeException.class, writer::commit);
			assertNotNull(findNativeCapacityCause(failure), "the actual consumed native failure must survive wrapping");
			assertEquals(1, store.operations.failedCommits.get());
			assertTrue(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			assertFalse(observer.hasStatement(SUBJECT, PREDICATE, replacement, false));
			assertEquals("urn:original:", observer.getNamespace("generation"));
			writer.rollback();

			writer.begin();
			writer.remove(SUBJECT, PREDICATE, OBJECT);
			writer.add(SUBJECT, PREDICATE, replacement);
			writer.setNamespace("generation", "urn:replacement:");
			writer.commit();
			assertFalse(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			assertTrue(observer.hasStatement(SUBJECT, PREDICATE, replacement, false));
			assertEquals("urn:replacement:", observer.getNamespace("generation"));
		} finally {
			repository.shutDown();
		}
	}

	private static Throwable findNativeCapacityCause(Throwable failure) {
		for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
			if (mdb_strerror(MDB_MAP_FULL).equals(cause.getMessage())) {
				return cause;
			}
		}
		return null;
	}

	private static long committedTransactionId(PersistentSetFactory<?> factory) throws IOException {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(factory.env, info));
			return info.me_last_txnid();
		}
	}

	private static final class CountingCacheStore extends LmdbStore {
		private final CountingOperations operations = new CountingOperations();
		private PersistentSetFactory<Long> cache;

		CountingCacheStore(File directory) {
			super(directory, new LmdbStoreConfig("spoc,ospc,psoc").setForceSync(false)
					.setSketchEstimatorEnabled(false));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchEnabled) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketchEnabled, ValueStore::new, TripleStore::new,
					cacheDirectory -> cache = new PersistentSetFactory<>(cacheDirectory, operations),
					LmdbFilterSelectivityStats::new);
		}
	}

	private static final class CountingOperations implements PersistentSetFactory.NativeTransactionOperations {
		private final AtomicInteger commitCalls = new AtomicInteger();
		private final AtomicInteger failedCommits = new AtomicInteger();
		private final AtomicBoolean failNextCommit = new AtomicBoolean();

		@Override
		public int commit(long transaction) {
			commitCalls.incrementAndGet();
			if (failNextCommit.compareAndSet(true, false)) {
				mdb_txn_abort(transaction);
				failedCommits.incrementAndGet();
				return MDB_MAP_FULL;
			}
			return mdb_txn_commit(transaction);
		}

		@Override
		public void abort(long transaction) {
			mdb_txn_abort(transaction);
		}
	}
}
